<script lang="ts">
 import {COMPACT_CONTENT_QUERY} from '$lib/responsive-layout';
 import {previewValues} from '$lib/widget-record-values';
 import {onMount,untrack} from 'svelte';import {localization} from '$lib/localization';import {apiData} from '$lib/api';
 import sandboxScript from '$lib/widget-sandbox.js.txt?raw';import RuntimeWidget from './RuntimeWidget.svelte';import type {WidgetDefinition,WidgetValues,WidgetRecord} from '$lib/widgets';
 import mobileTypography from '$lib/widget-mobile-typography.css?raw';
 import DetailModal from '../DetailModal.svelte';
 let {definition,instanceKey,configuration={},records=[],preview=false,measureOnly=false,size='',expanded=false,onHeight,language,theme,scale=1}:{definition:WidgetDefinition;instanceKey?:string;configuration?:WidgetValues;records?:Array<{recordKey:string;values:WidgetValues}>;preview?:boolean;measureOnly?:boolean;size?:string;expanded?:boolean;onHeight?:(height:number)=>void;language?:'ja'|'en';theme?:string;scale?:number}=$props();
 let documentUrl=$state('about:blank');let blobUrl:string|undefined;let frame=$state<HTMLIFrameElement>(),error=$state(''),running=$state(false),ready=$state(false),height=$state(240),full=$state(false);let fullHtml=$state('');let fullFromPointer=$state(false);let trigger=$state<HTMLElement|null>(null);let port:MessagePort|undefined;let memory:WidgetRecord[]=[];let active=true;let epoch=0;let initTimer:ReturnType<typeof setTimeout>|undefined;let connectListener:((event:MessageEvent)=>void)|undefined;
 let compact=$state(false),sizedViewport=$state(false);
 const calculator=$derived(['sph.calculator','sph.programmer_calculator'].includes(definition.id));
 const fillsHeight=$derived(!expanded&&(definition.id==='sph.world_clock'||(calculator&&!compact||['sph.personal_note','sph.stopwatch','sph.timer','sph.unit_converter'].includes(definition.id))&&(!preview||sizedViewport)));
 onMount(()=>{sizedViewport=!!frame?.closest('.preview-stage,.sized-preview-stage');const query=matchMedia(COMPACT_CONTENT_QUERY);const update=()=>compact=query.matches;update();query.addEventListener('change',update);return()=>query.removeEventListener('change',update);});
 const context=()=>{const hostTheme=document.documentElement.dataset.theme??'light';const tokens=Object.fromEntries(['--text','--surface','--surface-secondary','--border','--muted','--danger','--bg','--action-primary-background','--action-primary-background-hover','--action-primary-button-border','--action-primary-text'].map(key=>[key,getComputedStyle(document.documentElement).getPropertyValue(key).trim()]));return JSON.parse(JSON.stringify({language:language??$localization.displayLanguage,timeZone:$localization.timeZone,theme:theme??hostTheme,hostTheme,tokens,configuration,size,expanded,preview,width:(frame?.clientWidth??320)/scale,height:(frame?.clientHeight??240)/scale,compact,verticalAlign:definition.id==='sph.world_clock'?'center':fillsHeight?'stretch':'start',scale}));};
 const recordInput=()=>JSON.stringify(records.length?records:definition.storage?.initialRecords??[]);
 let recordSnapshot='';

 function stop(){active=false;clearTimeout(initTimer);epoch++;if(connectListener)window.removeEventListener('message',connectListener);connectListener=undefined;port?.postMessage({type:'stop'});port?.close();port=undefined;running=false;ready=false;if(blobUrl)URL.revokeObjectURL(blobUrl);blobUrl=undefined;documentUrl='about:blank';}
 function fail(message:string){stop();error=message;}
 async function request(method:string,args:unknown[]){
  if(method==='context')return context();
  if(!/^records\.(list|get|create|update|delete)$/.test(method)||!definition.storage)throw Error('Operation not available');
  const operation=method.slice(8);let query='';if(operation==='list'&&args[0]!==undefined){const q=args[0] as Record<string,unknown>;if(!q||typeof q!=='object'||Array.isArray(q)||Object.keys(q).some(k=>!['limit','offset','sortBy','sortOrder'].includes(k))||q.limit!==undefined&&(!Number.isSafeInteger(q.limit)||Number(q.limit)<1||Number(q.limit)>500)||q.offset!==undefined&&(!Number.isSafeInteger(q.offset)||Number(q.offset)<0)||q.sortBy!==undefined&&!['recordKey','createdAt','updatedAt'].includes(String(q.sortBy))||q.sortOrder!==undefined&&!['asc','desc'].includes(String(q.sortOrder)))throw Error('Invalid list options');query='?'+new URLSearchParams(Object.entries(q).map(([k,v])=>[k,String(v)])).toString();}if(operation==='create'||operation==='update'||operation==='delete')if(!definition.storage.operations[operation])throw Error('Storage operation not allowed');
  const key=args[0];if(operation!=='list'&&(typeof key!=='string'||!/^[a-zA-Z0-9][a-zA-Z0-9_-]{0,63}$/.test(key)))throw Error('Invalid record key');
  if(preview||!instanceKey){
   const old=memory.find(r=>r.recordKey===key);const checked=operation==='create'||operation==='update'?previewValues(definition.storage,args[operation==='create'?1:2]):undefined;const remaining=memory.filter(r=>r!==old).reduce((n,r)=>n+new TextEncoder().encode(JSON.stringify(r.values)).length,0);if(checked&&remaining+new TextEncoder().encode(JSON.stringify(checked)).length>(definition.storage.maxTotalBytes??1048576))throw Error('Storage capacity exceeded');if(operation==='list'){const q=(args[0]??{}) as {offset?:number;limit?:number;sortBy?:'recordKey'|'createdAt'|'updatedAt';sortOrder?:string};const sortBy=q.sortBy??'createdAt';return [...memory].sort((a,b)=>String(a[sortBy]).localeCompare(String(b[sortBy]))*(q.sortOrder==='desc'?-1:1)).slice(q.offset??0,(q.offset??0)+(q.limit??100));}if(operation==='get'){if(!old)throw Error('Record not found');return old;}
   if(operation==='create'){if(old||memory.length>=(definition.storage.maxRecords??1000))throw Error('Record conflict or limit');const row={recordKey:key as string,values:checked!,revision:1,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};memory=[...memory,row];return row;}
   if(!old||old.revision!==args[1])throw Error('Record conflict');if(operation==='delete'){memory=memory.filter(r=>r!==old);return null;}const row={...old,values:checked!,revision:old.revision+1};memory=memory.map(r=>r===old?row:r);return row;
  }
  const base=`/v1/employees/me/widget-instances/${encodeURIComponent(instanceKey)}/records`;
  const path=operation==='list'||operation==='create'?base+query:`${base}/${key}`;
  const body=operation==='create'?{recordKey:key,values:args[1]}:operation==='update'?{revision:args[1],values:args[2]}:operation==='delete'?{revision:args[1]}:undefined;
  const response=await fetch(path,{method:{list:'GET',get:'GET',create:'POST',update:'PUT',delete:'DELETE'}[operation],headers:{'Content-Type':'application/json'},...(body?{body:JSON.stringify(body)}:{}),cache:'no-store',signal:AbortSignal.timeout(15000)});
  if(!response.ok){if(response.status===401||response.status===403)fail($localization.displayLanguage==='ja'?'利用権限がありません。':'Widget access denied.');throw Error(response.status===409?'Record conflict':`Storage request failed (${response.status})`);}return apiData(response);
 }
 function start(){
  stop();if(!frame||!definition.runtime||measureOnly)return;active=true;running=true;ready=false;error='';recordSnapshot=recordInput();memory=JSON.parse(recordSnapshot).map((r:{recordKey:string;values:WidgetValues})=>({...r,revision:1,createdAt:'',updatedAt:''}));const current=epoch;let pending=0;
  const nonce=crypto.randomUUID().replaceAll('-','');const channel=new MessageChannel();port=channel.port1;
  port.onmessage=async e=>{const m=e.data;if(!active||current!==epoch)return;try{if(!m||new TextEncoder().encode(JSON.stringify(m)).length>131072)throw Error('Invalid message');if(m.type==='connected'){port?.postMessage({type:'boot',runtime:JSON.parse(JSON.stringify(definition.runtime)),context:context()});}else if(m.type==='ready'){ready=true;clearTimeout(initTimer);}else if(m.type==='error')fail(String(m.message).slice(0,300));else if(m.type==='height'){height=Math.max(80,Math.min(expanded?200000:4000,Number(m.height)||240));onHeight?.(height);}else if(m.type==='expand'){if(typeof m.html!=='string'||m.html.length>65536)throw Error('Expanded view limit');fullHtml=m.html;fullFromPointer=m.inputMethod==='pointer';trigger=frame??null;full=true;}else if(m.type==='copy'){if(typeof m.value==='string'&&m.value.length<=16000)await navigator.clipboard.writeText(m.value).then(()=>port?.postMessage({type:'copy-result',ok:true}),()=>port?.postMessage({type:'copy-result',ok:false}));}else if(m.type==='request'){if(!Number.isSafeInteger(m.id)||typeof m.method!=='string'||!Array.isArray(m.args)||++pending>8)throw Error('Request limit');try{const result=await request(m.method,m.args);if(new TextEncoder().encode(JSON.stringify(result)).length>131072)throw Error('Response too large; use a smaller list limit');if(active&&epoch===current)port?.postMessage({type:'response',id:m.id,data:result});}catch(error){if(active&&epoch===current)port?.postMessage({type:'response',id:m.id,error:error instanceof Error?error.message:'Request failed'});}finally{pending--;}}}catch(error){fail(error instanceof Error?error.message:'Widget protocol error');}};
  const code=sandboxScript;
  connectListener=e=>{if(active&&epoch===current&&e.source===frame?.contentWindow&&e.data?.type==='sph-frame-ready'&&e.data?.nonce===nonce){if(connectListener)window.removeEventListener('message',connectListener);frame.contentWindow?.postMessage({type:'sph-connect'},'*',[channel.port2]);}};window.addEventListener('message',connectListener);
  const documentSource=`<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'nonce-${nonce}'; style-src 'nonce-${nonce}'; style-src-attr 'unsafe-inline'; worker-src blob:; connect-src 'none'; img-src 'none'; font-src 'none'; frame-src 'none'; object-src 'none'; base-uri 'none'; form-action 'none'"><style nonce="${nonce}">:root{color-scheme:light dark}html,body{width:100%;height:100%;min-height:0;overflow:hidden;-webkit-text-size-adjust:100%;text-size-adjust:100%}*{box-sizing:border-box}body{margin:0;font:16px system-ui;color:var(--text,#172334);background:${expanded&&definition.id==='sph.personal_note'?'var(--bg,#f5f7fb)':'var(--surface,#fff)'}}button,input,select,textarea{font:inherit}button{cursor:pointer}#root{display:flow-root;min-height:80px;overflow-wrap:anywhere}</style><style id="custom-css" nonce="${nonce}"></style><style nonce="${nonce}">${mobileTypography}</style></head><body><div id="root"></div><script nonce="${nonce}">${code.replaceAll('<'+'/script','<\\/script')}<${'/script'}></body></html>`;blobUrl=URL.createObjectURL(new Blob([documentSource],{type:'text/html'}));documentUrl=blobUrl;const checkStartup=()=>{if(!active||ready||epoch!==current)return;if(document.hidden)initTimer=setTimeout(checkStartup,1000);else fail('Initialization timed out');};initTimer=setTimeout(checkStartup,15000);
 }
 onMount(()=>{if(!measureOnly)start();const observer=new MutationObserver(()=>port?.postMessage({type:'context',context:context()}));observer.observe(document.documentElement,{attributes:true,attributeFilter:['data-theme']});let width=0,viewportHeight=0;const resize=new ResizeObserver(()=>{if(frame&&(frame.clientWidth!==width||frame.clientHeight!==viewportHeight)){width=frame.clientWidth;viewportHeight=frame.clientHeight;port?.postMessage({type:'context',context:context()});}});if(frame)resize.observe(frame);return()=>{resize.disconnect();observer.disconnect();stop();};});
 $effect(()=>{configuration;size;language;theme;scale;compact;fillsHeight;$localization;port?.postMessage({type:'context',context:context()});});
 // SDK code may cache records in ready(). Reboot only an active preview when
 // its host draft changes, so that every widget receives the new isolated data.
 // Coalesce typing, and keep failed previews stopped.
 $effect(()=>{
  if(!preview||measureOnly)return;
  const next=recordInput();
  if(untrack(()=>!running||next===recordSnapshot))return;
  const timer=setTimeout(()=>{if(running&&next!==recordSnapshot)start();},120);
  return()=>clearTimeout(timer);
 });
</script>
<div class="runtime-widget" data-runtime-ready={ready} class:expanded class:clock-centered={definition.id==='sph.world_clock'}>
 {#if measureOnly}<div style="min-height:80px"></div>{:else}
 <iframe bind:this={frame} src={documentUrl} title={definition.name[(language??$localization.displayLanguage)==='ja'?'ja':'en']} sandbox="allow-scripts" referrerpolicy="no-referrer" style:height={fillsHeight?'100%':`${height}px`} style:display={error?'none':undefined}></iframe>
 {#if error}<p role="alert">{error}</p><button type="button" onclick={start}>{$localization.displayLanguage==='ja'?'再試行':'Retry'}</button>{/if}
 {/if}
</div>
{#if full}<DetailModal title={definition.name[$localization.displayLanguage==='ja'?'ja':'en']} titleId="runtime-full-title" closeLabel={$localization.displayLanguage==='ja'?'閉じる':'Close'} returnFocus={trigger} initialFocusFromPointer={fullFromPointer} onClose={()=>full=false}><RuntimeWidget definition={{...definition,runtime:{sdkVersion:1,html:fullHtml,css:definition.runtime?.css??'',javascript:'sph.ready(()=>{});'}}} {configuration} preview={true} {size} {scale} expanded={true}/></DetailModal>{/if}
<style>.runtime-widget{min-width:0;width:100%;height:100%;overflow:hidden}.runtime-widget.clock-centered iframe{min-height:0}.runtime-widget iframe{display:block;width:100%;min-height:80px;max-height:4000px;border:0;background:transparent}.runtime-widget.expanded iframe{max-height:200000px}.runtime-widget p{color:var(--danger);overflow-wrap:anywhere}button{padding:6px 12px;border:1px solid var(--border);border-radius:4px;background:var(--surface);color:var(--text)}</style>
